const ingaDays=[{"number":1,"title":"Zlatni list na prozoru","ribbon":"PRVA ETAPA · VRATA AKADEMIJE","story":[{"heading":"Avantura 1 · Tajna Starog hrasta","html":"<section class='story-scene single-story'><h3>Zlatni list na prozoru</h3><p>Jutro je počelo neobično. Na Inginom prozoru ležao je zlatni list koji je u zraku nacrtao stazu prema Velikoj šumi. Na starim vratima Inga je primijetila četiri zlatna početna slova. Složila ih je i dobila riječ VJERA. Vrata su se otvorila, a iz tame se začuo glas Mudre sove. Inga je zakoračila unutra, ne znajući da je upravo započela potragu za sedam ključeva znanja.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koju je riječ Inga dobila od zlatnih početnih slova?","options":["SNAGA","VJERA","BRZINA"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · Let’s Start!</small><h3>HELLO</h3><p class='english-sentence'>Hello! My name is Inga.</p><button class='english-speak' data-english='Hello! My name is Inga.'>🔊 Poslušaj</button><p>Pozdravi Mudru sovu i reci svoje ime.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Na Inginom prozoru ležao je list boje meda, iako u dvorištu nije bilo nijednog takvog stabla. Po njegovim žilicama svjetlucala su sitna slova, kao da ih je netko napisao mjesečinom.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"U četiri košarice nalazi se po 6 zlatnih listova. Inga je 5 listova stavila u bilježnicu. Koliko je listova ostalo u košaricama? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[19]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koju je riječ Inga dobila od zlatnih početnih slova? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":2,"title":"Put prema Velikoj šumi","ribbon":"DRUGA ETAPA · STAZA SVIJETLA","story":[{"heading":"Avantura 2 · Svjetiljka pažnje","html":"<section class='story-scene single-story'><h3>Put prema Velikoj šumi</h3><p>Mudra sova predala je Ingi plavu svjetiljku koja svijetli samo kada pažljivo promatra. Na prvom raskrižju Inga je požurila i svjetiljka se ugasila. Vratila se, pročitala znakove polako i uočila pravi put. Shvatila je da pažnja znači zastati, usporediti tragove i tek tada odlučiti. Na kraju staze čekao ju je prvi sjajni znak Akademije.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Zašto se svjetiljka ugasila na prvom raskrižju?","options":["Jer je Inga požurila i nije pogledala znakove.","Jer je nestalo baterije.","Jer je svanulo."],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Family</small><h3>FAMILY</h3><p class='english-sentence'>This is my family.</p><button class='english-speak' data-english='This is my family.'>🔊 Poslušaj</button><p>Imenuj članove svoje obitelji na engleskom.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Mudra sova predala je Ingi malu svjetiljku od plavog stakla. Upozorila ju je da se ona ne pali šibicom ni gumbom.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Na 5 stupova postavljene su po 3 lampice, a zatim su dodane još 4 lampice uz ulaz. Koliko lampica sada svijetli? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[19]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Zašto se svjetiljka ugasila na prvom raskrižju? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":3,"title":"Susret s Milom","ribbon":"TREĆA ETAPA · VJEVERIČINA KUĆICA","story":[{"heading":"Avantura 3 · Mila i izgubljena karta","html":"<section class='story-scene single-story'><h3>Susret s Milom</h3><p>U Akademiju je utrčala vjeverica Mila. Njezina karta Velike šume nestala je sa stola. Inga je pronašla lagane tragove papira, otvoren prozor i pero na grani. Nije optužila nikoga, nego je povezala tragove. Jak vjetar odnio je kartu do starog bora. Mila se nasmiješila, a karta je otkrila novu stazu koja vodi prema rijeci.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je zapravo odnijelo kartu s Milina stola?","options":["Bruno jež","Snažan vjetar","Mudra sova"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Family</small><h3>SISTER</h3><p class='english-sentence'>This is my sister.</p><button class='english-speak' data-english='This is my sister.'>🔊 Poslušaj</button><p>Odaberi: mother, father, brother ili sister.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Mila je u Akademiju utrčala toliko brzo da su joj lješnjaci ispali iz torbice. Karta Velike šume, jedina na kojoj su bili označeni skriveni prolazi, nestala je tijekom noći.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Mila ima 6 vrećica s po 4 lješnjaka. Sve ih ravnomjerno dijeli na 3 police. Koliko lješnjaka stavlja na svaku policu? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[8]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je zapravo odnijelo kartu s Milina stola? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":4,"title":"Dabrov most","ribbon":"ČETVRTA ETAPA · RIJEKA ZNANJA","story":[{"heading":"Avantura 4 · Dabrov most","html":"<section class='story-scene single-story'><h3>Dabrov most</h3><p>Kod rijeke je dabar Bor pokušavao popraviti most. Imao je nekoliko dasaka, ali nije znao koliko još nedostaje. Inga je prebrojila prazna mjesta, usporedila ih s pripremljenim daskama i izračunala razliku. Most je ponovno postao siguran. Dok su prelazili, ispod posljednje daske pronašli su znak drugog ključa.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Kako je Inga odredila koliko još dasaka treba?","options":["Nasumično je odabrala broj.","Pomnožila je broj dijelova i dasaka, pa oduzela već postavljene.","Pitala je vjevericu."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My House</small><h3>HOUSE</h3><p class='english-sentence'>This is my house.</p><button class='english-speak' data-english='This is my house.'>🔊 Poslušaj</button><p>Pokaži i imenuj: door, window, roof.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Dabrić Niko gradio je most preko brze Rijeke znanja. Imao je šest jednakih dijelova, a za svaki su mu trebale četiri daske.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Za 7 dijelova mosta trebaju po 3 daske. Dabrić već ima 9 dasaka. Koliko mu još dasaka nedostaje? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[12]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Kako je Inga odredila koliko još dasaka treba? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":5,"title":"Vrt zaboravljenih riječi","ribbon":"PETA ETAPA · ČAROBNI VRT","story":[{"heading":"Avantura 5 · Vrt zaboravljenih riječi","html":"<section class='story-scene single-story'><h3>Vrt zaboravljenih riječi</h3><p>S druge strane mosta nalazio se vrt u kojem su biljke izgubile svoja imena. Dvije su izgledale gotovo jednako, ali Inga je pažljivo usporedila oblik listova, boju cvjetova i miris. Sitni detalji pomogli su joj razlikovati biljke. Kada je pravilno pročitala njihove nazive, vrt je ponovno procvjetao, a među laticama se pojavila poruka.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je Ingi pomoglo razlikovati dvije slične biljke?","options":["Oblik listova","Visina ograde","Broj oblaka"],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My House</small><h3>KITCHEN</h3><p class='english-sentence'>The kitchen is in my house.</p><button class='english-speak' data-english='The kitchen is in my house.'>🔊 Poslušaj</button><p>Pronađi prostoriju: bedroom, kitchen ili bathroom.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „U čarobnom vrtu sve su pločice s imenima biljaka izblijedjele. Ruže su tvrdile da su tulipani, ljubičice su se skrivale među tratinčicama, a vrtlar Krtko nije znao kako ih ponovno razvrstati.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"U 8 redova posađeno je po 5 cvjetova. Vrtlar je uklonio 6 uvelih cvjetova. Koliko je zdravih cvjetova ostalo? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[34]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je Ingi pomoglo razlikovati dvije slične biljke? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":6,"title":"Sat koji je izgubio minute","ribbon":"ŠESTA ETAPA · TORANJ VREMENA","story":[{"heading":"Avantura 6 · Sat koji je izgubio minute","html":"<section class='story-scene single-story'><h3>Sat koji je izgubio minute</h3><p>Poruka je Ingu odvela do tornja sa satom koji je preskakao minute. Umjesto da nasumce okreće kazaljke, zapisala je niz vremena i pronašla pravilnost u kvaru. Svaki se četvrti korak ponavljao. Kada je postavila kazaljke na pravo mjesto, sat je zazvonio i otvorio tajni prolaz prema Zvjezdanoj knjižnici.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koji je niz Inga zapisala dok je promatrala kvar?","options":["10, 15, 20, 25","1, 3, 8, 20","50, 40, 25, 7"],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Birthday</small><h3>BIRTHDAY</h3><p class='english-sentence'>Happy birthday!</p><button class='english-speak' data-english='Happy birthday!'>🔊 Poslušaj</button><p>Izgovori brojeve od one do ten.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „U Tornju vremena veliki je sat prestao otkucavati. Kazaljke su se kretale, ali su preskakale svakih pet minuta.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Trideset zupčanika raspoređeno je u 5 jednakih skupina. Dvije skupine već su očišćene. Koliko zupčanika još treba očistiti? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[18]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koji je niz Inga zapisala dok je promatrala kvar? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":7,"title":"Zvjezdana knjižnica","ribbon":"SEDMA ETAPA · KNJIŽNICA NEBA","story":[{"heading":"Avantura 7 · Zvjezdana knjižnica","html":"<section class='story-scene single-story'><h3>Zvjezdana knjižnica</h3><p>U knjižnici su knjige svijetlile poput zvijezda. Na jednoj je stranici bila pjesma čija su prva slova redaka skrivala poruku. Inga ih je pročitala redom i otkrila smjer kojim treba krenuti. Mudra sova joj je objasnila da tekst ponekad govori više nego što se vidi na prvi pogled. Iza police otvorila su se vrata prema Srebrnom potoku.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Kako je Inga pronašla skrivenu poruku u pjesmi?","options":["Prebrojila je stranice.","Pročitala je prva slova stihova.","Zatvorila je knjigu."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Birthday</small><h3>CAKE</h3><p class='english-sentence'>This is my birthday cake.</p><button class='english-speak' data-english='This is my birthday cake.'>🔊 Poslušaj</button><p>Reci koliko svjećica vidiš.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Na vrhu brda nalazila se knjižnica bez polica. Knjige su lebdjele poput zvijezda, a do svake se moglo doći samo ako čitatelj postavi dobro pitanje.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Na 6 polica nalazi se po 7 knjiga. Učenici su posudili 8 knjiga. Koliko je knjiga ostalo? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[34]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Kako je Inga pronašla skrivenu poruku u pjesmi? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":8,"title":"Šapat Srebrnog potoka","ribbon":"OSMA ETAPA · SREBRNI POTOK","story":[{"heading":"Avantura 8 · Šapat Srebrnog potoka","html":"<section class='story-scene single-story'><h3>Šapat Srebrnog potoka</h3><p>Potok nije govorio glasom, nego valovima. Inga je mirno promatrala kako se slova pojavljuju na površini. Kada ih je spojila, pročitala je riječ STRPLJENJE. Voda se razmaknula i pokazala kamenčiće koji vode preko potoka. Na posljednjem kamenu čekala ju je Milina nova zagonetka.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koju je riječ potok ispisao na površini?","options":["SLUŠAJ","TRČI","SKAČI"],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Animals</small><h3>ANIMAL</h3><p class='english-sentence'>I like animals.</p><button class='english-speak' data-english='I like animals.'>🔊 Poslušaj</button><p>Imenuj tri životinje na engleskom.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Srebrni potok obično je pjevao, ali toga je jutra šaputao jedva čujno. Riječi su dolazile u kratkim dijelovima: ‘tri kamena… dva kruga… posljednji trag’.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Potok je pokazao 4 skupine s po 6 srebrnih kamenčića. Inga je 9 kamenčića vratila u vodu. Koliko ih je ostalo na obali? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[15]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koju je riječ potok ispisao na površini? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":9,"title":"Vjeveričina zagonetka","ribbon":"DEVETA ETAPA · STABLO ZAGONETKI","story":[{"heading":"Avantura 9 · Vjeveričina zagonetka","html":"<section class='story-scene single-story'><h3>Vjeveričina zagonetka</h3><p>Mila je donijela košaru žireva i zamolila Ingu da ih pravedno podijeli među tri prijatelja. Inga ih je rasporedila u jednake skupine i provjerila da nitko nije dobio više. Kada je izgovorila rezultat, jedan je žir zasjao jače od ostalih i pretvorio se u putokaz prema Mostu hrabrosti.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koliko je žireva dobio svaki od tri prijatelja?","options":["6","8","24"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Animals</small><h3>CAT</h3><p class='english-sentence'>The cat is small.</p><button class='english-speak' data-english='The cat is small.'>🔊 Poslušaj</button><p>Odaberi pridjev: big, small, fast ili slow.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Mila je pronašla stablo s sedam malih vrata. Na svakima je bio matematički znak, a iza samo jednih nalazio se trag.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"U 6 vrećica nalaze se po 4 žira. Žirevi se ravnomjerno dijele među 3 prijatelja. Koliko žireva dobiva svaki prijatelj? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[8]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koliko je žireva dobio svaki od tri prijatelja? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":10,"title":"Most hrabrosti","ribbon":"DESETA ETAPA · KLISURA ODLUKE","story":[{"heading":"Avantura 10 · Most hrabrosti","html":"<section class='story-scene single-story'><h3>Most hrabrosti</h3><p>Na mostu je svaka pogrešna pretpostavka pretvarala dasku u maglu. Inga nije odmah znala odgovor, ali nije odustala. Ponovno je pročitala pitanje, izdvojila važne podatke i pokušala drugim putem. Most se učvrstio. Mudra sova joj je rekla da hrabrost nije znati sve, nego pokušati ponovno kada nije lako.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je Inga učinila kada nije odmah znala odgovor?","options":["Odustala je.","Podijelila je problem na manje korake.","Nasumično je pogodila."],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Toys</small><h3>TOY</h3><p class='english-sentence'>This is my favourite toy.</p><button class='english-speak' data-english='This is my favourite toy.'>🔊 Poslušaj</button><p>Opiši igračku bojom i veličinom.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Ispred Inge protezao se most od svjetlosti. Svaka daska pojavila bi se tek kada izgovori nešto što zna, a nestala bi ako samo nagađa.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Graditelji imaju 5 košara s po 6 užadi. Potrošili su 8 užadi. Koliko užadi im je ostalo? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[22]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je Inga učinila kada nije odmah znala odgovor? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":11,"title":"Špijun izgubljenih riječi","ribbon":"JEDANAESTA ETAPA · GRAD TIHIH NATPISA","story":[{"heading":"Avantura 11 · Špijun izgubljenih riječi","html":"<section class='story-scene single-story'><h3>Špijun izgubljenih riječi</h3><p>U malom šumskom gradu iz rečenica su nestali glagoli. Bez njih nitko nije znao što se događa. Inga je pratila prazna mjesta, prepoznavala radnje i vraćala odgovarajuće riječi. Grad je ponovno oživio: ptice su pjevale, voda je tekla, a djeca su se igrala. Posljednji glagol pokazao je put prema Jezeru zrcala.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koja je vrsta riječi nestala iz gradskih rečenica?","options":["Imenice","Glagoli","Brojevi"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Toys</small><h3>BALL</h3><p class='english-sentence'>I have got a ball.</p><button class='english-speak' data-english='I have got a ball.'>🔊 Poslušaj</button><p>Vježbaj: I have got… / I haven’t got…</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „U Gradu tihih natpisa iz rečenica su nestali svi glagoli. Na pekarnici je pisalo ‘Pekar kruh’, na stanici ‘Autobus u sedam’, a na vratima škole ‘Učenici knjige’.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"U tiskari su 4 ladice s po 9 kartica. Patuljak je 12 kartica već posložio. Koliko kartica još treba posložiti? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[24]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koja je vrsta riječi nestala iz gradskih rečenica? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":12,"title":"Jezero zrcala","ribbon":"DVANAESTA ETAPA · JEZERO ODGOVORA","story":[{"heading":"Avantura 12 · Jezero zrcala","html":"<section class='story-scene single-story'><h3>Jezero zrcala</h3><p>Jezero je Ingi pokazivalo samo ono čega se bojala. Umjesto da se okrene, prisjetila se svega što je već naučila. Ključ nije bio na dnu vode, nego u odrazu starog drveta iza nje. Okrenula se i pronašla ga u šupljini. Jezero se smirilo, a na obali se pojavio Čuvar Zlatnih žireva.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Gdje je Inga pronašla ključ?","options":["U podstavi Miline torbice","U ptičjem gnijezdu","Na dnu jezera"],"answer":0},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Holidays</small><h3>HOLIDAY</h3><p class='english-sentence'>I am on holiday.</p><button class='english-speak' data-english='I am on holiday.'>🔊 Poslušaj</button><p>Reci: sun, sea, sand, boat.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Jezero zrcala pokazivalo je tri verzije istog događaja. U prvom odrazu Mila je ispustila ključ, u drugom ga je odnijela ptica, a u trećem je ključ cijelo vrijeme bio u džepu.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Na jezeru plovi 7 čamaca s po 4 putnika. Na prvoj postaji izašlo je 6 putnika. Koliko je putnika ostalo u čamcima? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[22]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Gdje je Inga pronašla ključ? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":13,"title":"Čuvar Zlatnih žireva","ribbon":"TRINAESTA ETAPA · RIZNICA ZNANJA","story":[{"heading":"Avantura 13 · Čuvar Zlatnih žireva","html":"<section class='story-scene single-story'><h3>Čuvar Zlatnih žireva</h3><p>Čuvar je otvorio riznicu punu sjajnih žireva, medalja i dragulja. Ipak, rekao je da najveće blago nije predmet. Inga je pogledala tragove svojih pokušaja, ispravljenih pogrešaka i pomoći prijateljima. Shvatila je da je najvažnije blago znanje koje je stekla i hrabrost da nastavi učiti.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Što je bilo najvažnije blago u riznici?","options":["Novac","Priče, izumi i pitanja učenika","Zlatne krune"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Holidays</small><h3>BOAT</h3><p class='english-sentence'>The boat is on the sea.</p><button class='english-speak' data-english='The boat is on the sea.'>🔊 Poslušaj</button><p>Složi rečenicu od četiri riječi.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „Čuvar Zlatnih žireva, veliki jazavac Argo, nije dopuštao ulazak u riznicu bez dokaza da posjetitelj razumije vrijednost znanja. Nije tražio lozinku, nego tri objašnjenja: kako učimo iz pogreške, zašto provjeravamo odgovor i kako pomažemo drugome.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Na 8 polica nalazi se po 5 žireva. Dvanaest je podijeljeno učenicima, a ostatak je raspoređen u 4 kutije. Koliko žireva dolazi u svaku kutiju? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[7]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Što je bilo najvažnije blago u riznici? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]},{"number":14,"title":"Prvi ključ Akademije","ribbon":"ČETRNAESTA ETAPA · DVORANA KLJUČEVA","story":[{"heading":"Avantura 14 · Prvi ključ Akademije","html":"<section class='story-scene single-story'><h3>Prvi ključ Akademije</h3><p>U Dvorani ključeva Inga je rasporedila sve simbole koje je prikupila. Četiri kruga na vratima zasjala su, ali sredina je ostala prazna. Tada je postavila pitanje: „Što mogu pokušati sljedeće?” U sredini se pojavio zlatni ključ. Vrata su se otvorila prema novim područjima Velike šume. Prva velika pustolovina završila je, ali nova je upravo počinjala.</p></section><aside class='reading-note'><img src='assets/owl-professional.png' alt='Mudra sova'><span><b>Podsjetnik Mudre sove</b> Čitaj mirno. Kad završiš, ukratko prepričaj što se dogodilo.</span></aside>"},{"heading":"Čitanje s razumijevanjem","question":"Koje je pitanje otvorilo posljednji dio vrata?","options":["Tko je najbrži?","Što mogu pokušati sljedeće?","Gdje je moje blago?"],"answer":1},{"heading":"English with Wise Owl","html":"<div class='english-card'><span class='english-flag'>🇬🇧</span><small>SMILES 2 · My Magazine Review</small><h3>I CAN</h3><p class='english-sentence'>I can read, count and learn.</p><button class='english-speak' data-english='I can read, count and learn.'>🔊 Poslušaj</button><p>Ponovi riječi iz svih šest modula.</p></div>"},{"heading":"Radna bilježnica na papiru","html":"<div class='paper-workbook-intro'><b>✍️ Pripremi bilježnicu i olovku</b><p>Sljedeći zadatci rješavaju se na papiru. Prepiši pažljivo, pokaži račun i provjeri napisano.</p><span>Predviđeno vrijeme: 8–10 minuta</span></div>","button":true}],"tasks":[{"skill":"Pisanje","title":"1. Prepiši uredno","text":"Prepiši u bilježnicu ove dvije rečenice iz avanture: „U Dvorani ključeva Inga je rasporedila sve predmete koje je prikupila: kompas, svjetiljku, kartu, čavao, sjemenke, zvijezdu, kapljicu, drvene oblike, značku, pero, zrcalo i poruke prijatelja. Svaki je predmet predstavljao jednu vještinu.”","paper":true},{"skill":"Hrvatski jezik","title":"2. Istraži rečenice","text":"U prepisanim rečenicama plavom bojom podcrtaj imenice, a zelenom zaokruži glagole. Zatim napiši jednu svoju rečenicu o pustolovini.","paper":true},{"skill":"Matematika","title":"3. Zadatak u više koraka","text":"Inga je prikupila 7 skupina s po 4 znaka. Šest je znakova već upotrijebila na vratima. Koliko joj je znakova ostalo? U bilježnici napiši račun u najmanje dva koraka i odgovor punom rečenicom.","answers":[22]},{"skill":"Čitanje s razumijevanjem","title":"4. Odgovori punom rečenicom","text":"Koje je pitanje otvorilo posljednji dio vrata? Odgovor napiši u bilježnicu punom rečenicom.","paper":true}]}];

