function showView(id){views.forEach(v=>v.classList.toggle("active",v.id===id));window.scrollTo({top:0,behavior:"smooth"})}
function showToast(text){toast.textContent=text;toast.classList.add("show");setTimeout(()=>toast.classList.remove("show"),2400)}
let selectedVoiceName=localStorage.getItem("mudra.voice.name")||"";
let availableVoices=[];
let activeUtterance=null;
const MALE_HINT=/Matej|Male|Muški|Guy|Ryan|George|Mark|David|Daniel|James|Thomas|Microsoft.*(Matej|Male)|Google.*male/i;
const FEMALE_HINT=/Gabrijela|Lana|Helena|Ivana|Sonia|Aria|Jenny|Zira|Hazel|Susan|Samantha|Victoria|Moira|Tessa|Karen|Ava|Joanna|Emma|Olivia|Maja|Milena|Vesna|Ana|Sara|Female|Ženski/i;
function voiceScore(v,lang){
  const l=(v.lang||"").toLowerCase(),n=v.name||"";let score=0;
  if(lang.startsWith("hr")){
    if(l.startsWith("hr"))score+=150;else if(/^(bs|sr|sl)/.test(l))score+=85;else if(l.startsWith("en"))score+=10;
    if(MALE_HINT.test(n))score+=90;
    if(FEMALE_HINT.test(n))score-=35;
  }else{
    if(l.startsWith("en-gb"))score+=105;else if(l.startsWith("en"))score+=90;
    if(MALE_HINT.test(n))score+=35;
  }
  if(/Natural|Neural|Online/i.test(n))score+=25;
  if(v.localService)score+=5;
  return score;
}
function sortedVoices(lang){return [...availableVoices].sort((a,b)=>voiceScore(b,lang)-voiceScore(a,lang))}
function autoVoice(lang="hr-HR"){
  const isCroatian=lang.toLowerCase().startsWith("hr");
  if(selectedVoiceName){
    const exact=availableVoices.find(v=>v.name===selectedVoiceName);
    if(exact&&(isCroatian?/^(hr|bs|sr|sl)/i.test(exact.lang||""):true))return exact;
  }
  const ranked=sortedVoices(lang);
  if(isCroatian){
    return ranked.find(v=>(v.lang||"").toLowerCase().startsWith("hr")&&MALE_HINT.test(v.name))
      || ranked.find(v=>(v.lang||"").toLowerCase().startsWith("hr"))
      || ranked.find(v=>/^(bs|sr|sl)/i.test(v.lang||"")&&MALE_HINT.test(v.name))
      || ranked.find(v=>/^(bs|sr|sl)/i.test(v.lang||""))
      || null;
  }
  return ranked.find(v=>(v.lang||"").toLowerCase().startsWith("en")&&MALE_HINT.test(v.name))
    || ranked.find(v=>(v.lang||"").toLowerCase().startsWith("en"))
    || null;
}
function refreshVoices(){
  availableVoices=speechSynthesis.getVoices();
  const sel=document.getElementById("voiceSelect");
  if(sel){
    const list=[...new Map(sortedVoices("hr-HR").filter(v=>/^(hr|bs|sr|sl)/i.test(v.lang||"")).map(v=>[v.name,v])).values()];
    sel.innerHTML=list.map(v=>`<option value="${v.name}" ${v.name===selectedVoiceName?"selected":""}>${MALE_HINT.test(v.name)?"Muški · ":""}${v.name} — ${v.lang}</option>`).join("")||`<option value="">Na uređaju nema hrvatskog ili srodnog TTS glasa</option>`;
    if(!selectedVoiceName&&list[0]){selectedVoiceName=list[0].name;sel.value=list[0].name;localStorage.setItem("mudra.voice.name",selectedVoiceName)}
  }
  updateVoiceStatus();
}
function updateVoiceStatus(){
  const v=autoVoice("hr-HR"),el=document.getElementById("voiceStatus");
  if(el)el.textContent=v?`TTS glas Mudre sove: ${v.name}`:"TTS glas nije pronađen – otvori Postavke glasa";
}
function setSpeechButtons(state){
  document.querySelectorAll('[data-action="pause-speech"]').forEach(b=>{b.textContent=state==="paused"?"Nastavi":"Pauza"});
}
function speak(text,lang="hr-HR"){
  if(!("speechSynthesis" in window)){showToast("Ovaj preglednik ne podržava čitanje naglas.");return}
  speechSynthesis.cancel();
  const clean=String(text).replace(/[🌰⭐🦉📖✏️🐰🐻🐸🐿️🦀🦕🔊]/g,"").replace(/\s+/g," ").trim();
  const u=new SpeechSynthesisUtterance(clean);
  activeUtterance=u;
  const english=lang.toLowerCase().startsWith("en");
  u.lang=english?"en-GB":"hr-HR";
  u.rate=english?.86:.82;
  u.pitch=english?1.0:.88;
  u.volume=1;
  const v=autoVoice(u.lang);
  if(v)u.voice=v;
  u.onstart=()=>setSpeechButtons("playing");
  u.onend=u.onerror=()=>{activeUtterance=null;setSpeechButtons("stopped")};
  speechSynthesis.speak(u);
}
function pauseOrResumeSpeech(){
  if(speechSynthesis.speaking&&!speechSynthesis.paused){speechSynthesis.pause();setSpeechButtons("paused")}
  else if(speechSynthesis.paused){speechSynthesis.resume();setSpeechButtons("playing")}
}
function stopSpeech(){speechSynthesis.cancel();activeUtterance=null;setSpeechButtons("stopped")}
function nikoInstructionSpeech(s){return `${s.speech} ${s.instruction} Napravi ${s.reps} ponavljanja. Radi polako i sigurno.`}
function doneCount(p){const days=p==="inga"?ingaDays:nikoDays;return days.filter(d=>localStorage.getItem(`v42.${p}.day${d.number}`)==="1").length}
function renderScore(){document.getElementById("totalScore").textContent=doneCount("inga")+doneCount("niko");document.getElementById("ingaAcorns").textContent=doneCount("inga")}
function openAcademy(p){
  profile=p;localStorage.setItem("v42.profile",p);
  const days=p==="inga"?ingaDays:nikoDays,done=doneCount(p),academy=document.getElementById("academyView");
  academy.classList.toggle("academy-inga",p==="inga");academy.classList.toggle("academy-niko",p==="niko");
  document.getElementById("academyLabel").textContent=p==="inga"?"INGINA AKADEMIJA ZNANJA":"NIKINA AKADEMIJA ISTRAŽIVAČA";
  document.getElementById("academyTitle").textContent=p==="inga"?"Inga, odaberi avanturu":"Niko, odaberi istraživački dan";
  document.getElementById("missionTitle").textContent=p==="inga"?"Tajna Starog hrasta":"Istraživačke pustolovine";
  document.getElementById("missionText").textContent=p==="inga"?"Čitanje, matematika, hrvatski i English with Wise Owl.":"Slova, slogovi, brojevi, boje i pokret.";
  document.getElementById("academyBadge").textContent="DANI 1–14";document.getElementById("profileProgress").textContent=done+" / 14 dana";
  document.getElementById("profileRewards").innerHTML=Array.from({length:14},(_,i)=>`<span class="reward-acorn ${i<done?"earned":""}" aria-label="${i<done?"Osvojeni":"Neosvojeni"} Zlatni žir"><img src="assets/acorn-3d.png" alt=""></span>`).join("");
  const list=document.getElementById("dayList");list.className=`day-list ${p}-day-list`;
  list.innerHTML=days.map((d,i)=>`<button class="day-item ${localStorage.getItem(`v42.${p}.day${d.number}`)==="1"?"completed":""}" data-day="${i}"><strong>${d.number}</strong><small>${d.title}</small><em>★</em></button>`).join("");
  list.querySelectorAll("[data-day]").forEach(b=>b.onclick=()=>p==="inga"?startIngaDay(+b.dataset.day):startNikoDay(+b.dataset.day));
  document.querySelector("[data-action=start-day]").onclick=()=>p==="inga"?startIngaDay(Math.min(done,13)):startNikoDay(Math.min(done,13));showView("academyView")
}
function startIngaDay(i){ingaDayIndex=i;ingaPageIndex=0;renderIngaPage();showView("ingaDayView");setTimeout(()=>speak(`Avantura ${ingaDays[i].number}: ${ingaDays[i].title}. Čitaj polako i uživaj u priči.`,"hr-HR"),300)}
function renderIngaPage(){const d=ingaDays[ingaDayIndex],p=d.story[ingaPageIndex];document.getElementById("ingaDayLabel").textContent=`INGA · DAN ${d.number}`;document.getElementById("ingaDayTitle").textContent=d.title;document.getElementById("ingaChapterRibbon").textContent=d.ribbon;document.getElementById("ingaPageHeading").textContent=p.heading;const c=document.getElementById("ingaPageContent"),a=document.getElementById("ingaInteractiveArea");c.innerHTML=p.html||"";a.innerHTML="";if(p.question){a.innerHTML=`<div class="comprehension-box"><h3>🔎 ${p.question}</h3><div class="answer-options">${p.options.map((x,i)=>`<button class="answer-option" data-a="${i}">${x}</button>`).join("")}</div></div>`;a.querySelectorAll(".answer-option").forEach(b=>b.onclick=()=>{if(+b.dataset.a===p.answer){b.classList.add("correct");speak("Bravo Inga. Pažljivo si pročitala.")}else{b.classList.add("wrong");speak("Dobar pokušaj. Pogledaj tekst još jednom.");setTimeout(()=>b.classList.remove("wrong"),800)}})}if(p.sequence)a.innerHTML=`<div class="comprehension-box"><h3>🧩 Redoslijed događaja</h3><div class="sequence-list">${p.sequence.map((x,i)=>`<div class="sequence-item"><b>${i+1}.</b> ${x}</div>`).join("")}</div></div>`;if(p.button){a.innerHTML='<button class="primary wide" id="openWB">✏️ Otvori radnu bilježnicu</button>';document.getElementById("openWB").onclick=openWorkbook}document.querySelectorAll(".english-speak").forEach(b=>b.onclick=()=>speak(b.dataset.english,"en-GB"));document.getElementById("ingaPageCount").textContent=`${ingaPageIndex+1} / ${d.story.length}`;document.getElementById("ingaPrev").disabled=ingaPageIndex===0;document.getElementById("ingaNext").disabled=ingaPageIndex===d.story.length-1;document.getElementById("ingaPageDots").innerHTML=d.story.map((_,i)=>`<span class="page-dot ${i<ingaPageIndex?"done":i===ingaPageIndex?"active":""}"></span>`).join("");c.style.fontSize=`calc(clamp(27px,3vw,38px) * ${readingSize})`}
function turn(n){const x=ingaPageIndex+n;if(x<0||x>=ingaDays[ingaDayIndex].story.length)return;const p=document.getElementById("ingaBookPage");p.classList.add("turning");setTimeout(()=>{ingaPageIndex=x;renderIngaPage();flashStrategy()},180);setTimeout(()=>p.classList.remove("turning"),430)}
function workbookMath(day){
  const tables=[2,3,4,5,6,7,8,9],a=tables[(day-1)%tables.length],b=tables[(day+2)%tables.length];
  const mult=Array.from({length:6},(_,i)=>{const x=2+((i+day)%8),y=i%2?a:b;return {label:`${x} × ${y}`,answer:x*y};});
  const div=Array.from({length:6},(_,i)=>{const y=i%2?a:b,x=2+((i+day+1)%8);return {label:`${x*y} ÷ ${y}`,answer:x};});
  return {mult,div};
}
function mathRow(item,type,index){return `<div class="digital-math-row" data-math-answer="${item.answer}"><span>${index+1}) ${item.label} =</span><input type="number" inputmode="numeric" aria-label="Odgovor na ${type} ${index+1}"><button type="button" class="math-check-button">Provjeri</button><i class="math-result" aria-live="polite"></i></div>`}
function bindWorkbookMath(){
  document.querySelectorAll('.digital-math-row').forEach(row=>{const input=row.querySelector('input'),button=row.querySelector('button'),result=row.querySelector('.math-result');button.onclick=()=>{const ok=Number(input.value)===Number(row.dataset.mathAnswer);row.classList.toggle('correct',ok);row.classList.toggle('wrong',!ok);result.textContent=ok?'✓':'Pokušaj ponovno';speak(ok?'Bravo Inga. Točan rezultat.':'Dobar pokušaj. Izračunaj još jednom.','hr-HR')}});
  const all=document.getElementById('checkAllMath');if(all)all.onclick=()=>{let ok=0,total=0;document.querySelectorAll('.digital-math-row').forEach(row=>{total++;const input=row.querySelector('input'),good=Number(input.value)===Number(row.dataset.mathAnswer)&&input.value!=='';row.classList.toggle('correct',good);row.classList.toggle('wrong',!good);row.querySelector('.math-result').textContent=good?'✓':'Provjeri';if(good)ok++});speak(ok===total?'Bravo Inga. Svi rezultati su točni.':`Točno je ${ok} od ${total} rezultata. Provjeri ostale zadatke.`,'hr-HR')}
}

function naturePrompt(day){
  const prompts=[
    "Inga je pronašla list boje meda. Kojem godišnjem dobu najčešće pripada takav list? Napiši dvije promjene koje tada primjećujemo u prirodi.",
    "Svjetiljka je vodila Ingu kroz šumu. Napiši zašto je dnevna svjetlost važna biljkama i ljudima.",
    "Mila je pratila tragove u šumi. Navedi dva primjera tragova koje životinje mogu ostaviti u prirodi.",
    "Dabrovi grade nastambe uz vodu. Napiši kako se zove njihova nastamba i zašto im je voda važna.",
    "U vrtu rastu različite biljke. Navedi što je biljkama potrebno za rast i razvoj.",
    "Vrijeme mjerimo satom. Objasni razliku između jutra, podneva i večeri.",
    "Zvijezde vidimo noću. Napiši što se na nebu najčešće vidi danju, a što noću.",
    "Potok teče kroz šumu. Napiši dva razloga zbog kojih moramo čuvati vodu čistom.",
    "Vjeverica skuplja hranu. Napiši kako se životinje pripremaju za hladnije dane.",
    "Most povezuje dvije obale. Navedi jedan prirodni i jedan izgrađeni objekt u svom mjestu.",
    "Inga je tražila izgubljene riječi. Napiši zašto ljudi koriste znakove i simbole u prometu i svakodnevnom životu.",
    "Jezero je stanište mnogih bića. Navedi dvije životinje i jednu biljku koje mogu živjeti uz jezero.",
    "Žir je plod hrasta. Napiši kako iz žira može nastati novo stablo.",
    "Akademija se nalazi u zajednici šumskih stanovnika. Napiši dvije obveze koje pomažu da zajednica dobro funkcionira."
  ];
  return prompts[(day-1)%prompts.length];
}

function openWorkbook(){
  const d=ingaDays[ingaDayIndex],m=build17MathThemes[d.number-1]||build17MathThemes[0];
  document.getElementById("workbookTitle").textContent=d.title;document.getElementById("workbookDayTitle").textContent=`Dan ${d.number} · ${d.title}`;
  const writing=d.tasks.find(t=>t.skill==="Pisanje"),croatian=d.tasks.find(t=>t.skill==="Hrvatski jezik"),word=d.tasks.find(t=>t.skill==="Matematika"),reading=d.tasks.find(t=>t.skill==="Čitanje s razumijevanjem"),h=document.getElementById("ingaTasksText");
  h.innerHTML=`<section class="daily-challenge"><img class="challenge-owl" src="assets/owl-professional.png" alt="Mudra sova"><div><small>DANAŠNJI IZAZOV MUDRE SOVE</small><p>Rješavaj mirno i uredno. Ako pogriješiš, ispravi i pokušaj ponovno – tako znanje raste.</p></div></section>
  <section class="workbook-one-page"><div class="wb-language"><span class="skill-tag">HRVATSKI JEZIK I PISANJE</span><h3>1. Prepiši i istraži rečenice</h3><p>${writing?writing.text:""}</p><p><b>Zatim:</b> ${croatian?croatian.text:""}</p><p class="wb-reading"><b>Čitanje s razumijevanjem:</b> ${reading?reading.text:""}</p><div class="word-problem"><b>3. Tekstualni zadatak</b><p>${word?word.text:""}</p></div><div class="nature-task"><b>4. Priroda i društvo</b><p>${naturePrompt(d.number)}</p></div></div>
  <div class="wb-math"><span class="skill-tag">MATEMATIKA</span><h3>2. ${m.title}</h3><p class="math-note">${m.note}</p><div class="math-columns"><div><b>${m.leftTitle}</b>${m.left.map((x,i)=>mathRow(x,m.leftTitle,i)).join('')}</div><div><b>${m.rightTitle}</b>${m.right.map((x,i)=>mathRow(x,m.rightTitle,i)).join('')}</div></div><button id="checkAllMath" class="check-all-math" type="button">✓ Provjeri sve rezultate</button></div></section>
  <label class="paper-check workbook-finish"><input type="checkbox" id="paperComplete"> Sve sam prepisala, izračunala i provjerila.</label>`;
  bindWorkbookMath();const check=document.getElementById("paperComplete");if(check)check.onchange=()=>{if(check.checked)speak("Bravo Inga. Završila si radnu bilježnicu i pažljivo provjerila zadatke.","hr-HR")};showView("ingaTasksView")
}
function taskHTML(t,i){
  if(t.paper)return `<section class="v41-task paper-task" data-box="${i}"><span class="skill-tag">${t.skill}</span><h3>${t.title}</h3><p>${t.text}</p><label class="paper-check"><input type="checkbox" data-paper-done> Završila sam u bilježnici</label><div class="feedback"></div></section>`;
  const x=t.answers?t.answers.map((_,j)=>`<input type="number" data-field="${j}">`).join(" "):`<input type="text" data-field="0" style="width:100%" placeholder="Upiši odgovor">`;
  return `<section class="v41-task" data-box="${i}"><span class="skill-tag">${t.skill}</span><h3>${t.title}</h3><p>${t.text}</p>${x}<button class="check-task" data-task="${i}">Provjeri</button><div class="feedback"></div></section>`
}
function norm(s){return String(s).trim().toLowerCase().replace(/[.!?]/g,"").replace(/\s+/g," ")}
function checkTask(i){const t=ingaDays[ingaDayIndex].tasks[i],b=document.querySelector(`[data-box="${i}"]`),f=b.querySelector(".feedback");let ok=false;if(t.answers){const v=[...b.querySelectorAll("[data-field]")].map(x=>+x.value);ok=v.every((x,j)=>x===t.answers[j])}else{const v=b.querySelector("[data-field]").value.trim();ok=norm(v)===norm(t.wordAnswer)||norm(t.wordAnswer).includes(norm(v))&&v.length>2}f.textContent=ok?"Bravo! Točno riješeno. ✓":"Pročitaj uputu još jednom i pokušaj ponovno.";f.className="feedback "+(ok?"good":"try");speak(ok?"Bravo Inga. Odlično si riješila zadatak.":"Dobar pokušaj. Pokušaj ponovno.")}
