const nikoLabels={squirrel:"VJEVERICA",hedgehog:"JEŽ",acorn:"ŽIR",leaf:"LIST",rabbit:"ZEKO",owl:"SOVA",mushroom:"GLJIVA",strawberry:"JAGODA"};
function nikoAsset(key){
 const special={mushroom:"assets/niko3d/mushroom.png",strawberry:"assets/niko3d/strawberry.png"};
 return special[key]||`assets/niko3d/${key}.png`
}
function nikoLabel(key){return nikoLabels[key]||key}
function renderNiko(){
 const d=nikoDays[nikoDayIndex],s=d.steps[nikoStep],a=document.getElementById("nikoActivity"),n=document.getElementById("nikoNext");
 document.getElementById("nikoDayLabel").textContent=`NIKO · DAN ${d.number}`;
 document.getElementById("nikoStepTitle").textContent=s.title;
 document.getElementById("nikoSpeech").textContent=s.speech;
 n.disabled=true;n.textContent=nikoStep===d.steps.length-1?"Završi dan ⭐":"Sljedeće →";
 const success=(button)=>{button.classList.add("correct");n.disabled=false;speak("Bravo Niko!")};
 const fail=(button)=>{button.classList.add("wrong");speak("Pokušaj ponovno.");setTimeout(()=>button.classList.remove("wrong"),650)};
 if(s.type==="picture"){
   a.innerHTML=`<div class="niko-question"><h3>${s.prompt}</h3><div class="choice-grid picture-choice-grid">${s.choices.map(k=>`<button class="choice picture-choice" data-v="${k}"><img src="${nikoAsset(k)}" alt="${nikoLabel(k)}"><span>${nikoLabel(k)}</span></button>`).join("")}</div></div>`;
   a.querySelectorAll(".choice").forEach(b=>b.onclick=()=>{
     if(b.dataset.v===s.answer){a.querySelectorAll(".choice").forEach(x=>{x.disabled=true;x.classList.remove("wrong")});success(b)}else fail(b)
   });
 }else if(s.type==="addition"){
   const pics=(count,key)=>Array.from({length:count},()=>`<img src="${nikoAsset(key)}" alt="">`).join("");
   a.innerHTML=`<div class="niko-learning-card addition-card"><h3>Zbrajanje do 10</h3><p>Prebroji slike i dodirni točan rezultat.</p><div class="addition-row"><div class="object-group">${pics(s.left,s.object)}</div><b>+</b><div class="object-group">${pics(s.right,s.object)}</div><b>=</b><strong>?</strong></div><div class="number-options">${s.choices.map(v=>`<button class="choice number-choice" data-v="${v}">${v}</button>`).join("")}</div></div>`;
   a.querySelectorAll(".choice").forEach(b=>+b.dataset.v===s.answer?b.onclick=()=>success(b):b.onclick=()=>fail(b));
 }else if(s.type==="syllables"){
   a.innerHTML=`<div class="niko-learning-card syllable-card"><h3>Koliko slogova čuješ?</h3><img class="syllable-picture" src="${nikoAsset(s.image)}" alt="${s.word}"><div class="syllable-word">${s.word}</div><div class="number-options">${s.choices.map(v=>`<button class="choice number-choice" data-v="${v}">${v}</button>`).join("")}</div></div>`;
   a.querySelectorAll(".choice").forEach(b=>+b.dataset.v===s.syllables?b.onclick=()=>success(b):b.onclick=()=>fail(b));
 }else if(s.movement){
   const phases=s.phases||["Pripremi se","Napravi pokret","Vrati se u početni položaj"];
   const rabbitFrames=s.animalAsset==="rabbit"?["rabbit-stand1.png",s.motion==="squat"?"rabbit-squat.png":"rabbit-stand2.png","rabbit-stand2.png"]:null;
   const frames=phases.map((label,i)=>{
     const src=s.frames?.[i]|| (rabbitFrames?`assets/niko3d/${rabbitFrames[i]}`:nikoAsset(s.animalAsset));
     const frameClass=s.frames?" frame-art":"";
     return `<div class="mission-phase phase-${i} motion-${s.motion||"demo"}${frameClass}"><div class="phase-number">${i+1}</div><div class="phase-animal"><img src="${src}" alt="Korak ${i+1}: ${label}"></div><b>${label}</b></div>`;
   }).join("");
   a.innerHTML=`<div class="simple-card movement-card build23-mission"><div class="mission-demo" aria-label="Demonstracija vježbe u tri koraka"><div class="mission-phases">${frames}</div><div class="phase-progress"><span></span><span></span><span></span></div></div><div class="spoken-guide"><div><small>MUDRA SOVA GOVORI</small><h2>${s.exercise}</h2></div></div><p class="movement-instruction">${s.instruction}</p><button class="secondary listen-instruction" id="listenInstruction">Poslušaj uputu</button><button class="primary" id="playDemo">▶ Pokaži vježbu</button><div class="rep-counter"><b id="repCount">0</b> / ${s.reps}</div><button class="success" id="doRep">Napravio sam jedno ponavljanje</button></div>`;
   let count=0,phase=0,timer=null;
   const showPhase=(idx)=>{phase=idx;document.querySelectorAll('.mission-phase').forEach((el,i)=>el.classList.toggle('active',i===idx));document.querySelectorAll('.phase-progress span').forEach((el,i)=>el.classList.toggle('active',i===idx))};
   const playDemo=()=>{window.clearInterval(timer);showPhase(0);speak(phases[0]);let i=0;timer=setInterval(()=>{i++;if(i>=phases.length){clearInterval(timer);return}showPhase(i);speak(phases[i])},1800)};
   showPhase(0);
   document.getElementById("listenInstruction").onclick=()=>speak(`${s.exercise}. ${s.instruction}`);
   document.getElementById("playDemo").onclick=playDemo;
   document.getElementById("doRep").onclick=()=>{count++;document.getElementById("repCount").textContent=count;if(count>=s.reps){n.disabled=false;document.getElementById("doRep").disabled=true;window.clearInterval(timer);speak("Bravo Niko. Pokretna misija je završena.")}};
 }
 setTimeout(()=>speak(s.speech),250)
}
